import{_ as l,c as s,o as i,a2 as n}from"./chunks/framework.Cqt7uvsz.js";const e="/assets/1.Da26YBGi.png",r="/assets/2.Cb-v4D9Y.png",t="/assets/3.BlouYY_D.png",o="/assets/4.Cl60TVol.png",p="/assets/5.DJJMCoQz.png",q=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"notes/计算机系统/线程-进程-协程.md","filePath":"notes/计算机系统/线程-进程-协程.md","lastUpdated":1766579221000}'),h={name:"notes/计算机系统/线程-进程-协程.md"};function c(d,a,u,m,b,_){return i(),s("div",null,a[0]||(a[0]=[n(`<h2 id="进程、线程、协程" tabindex="-1">进程、线程、协程 <a class="header-anchor" href="#进程、线程、协程" aria-label="Permalink to &quot;进程、线程、协程&quot;">​</a></h2><p>参考：<a href="https://juejin.cn/post/6904821235801128967" target="_blank" rel="noreferrer">工作2年，有些人竟然还不懂进程、线程、协程之间的关系！ - 掘金 (juejin.cn)</a></p><p>我们都知道计算机的核心是CPU，它承担了所有的计算任务；而操作系统是计算机的管理者，它负责任务的调度、资源的分配和管理，统领整个计算机硬件；应用程序则是具有某种功能的程序，程序是运行于操作系统之上的。</p><h3 id="进程" tabindex="-1">进程 <a class="header-anchor" href="#进程" aria-label="Permalink to &quot;进程&quot;">​</a></h3><ol><li><p>是并发执行的程序在执行过程中分配和管理资源的基本单位，是一个动态概念，竞争计算机系统资源的基本单。</p></li><li><p>一个在<a href="https://so.csdn.net/so/search?q=%E5%86%85%E5%AD%98&amp;spm=1001.2101.3001.7020" target="_blank" rel="noreferrer">内存</a>中运行的应用程序。每个进程都有自己独立的一块内存空间，一个进程可以有多个线程，比如在Windows系统中，一个运行的xx.exe就是一个进程。</p></li></ol><p>进程是一个具有一定独立功能的程序在一个数据集上的一次动态执行的过程，是操作系统进行资源分配和调度的一个独立单位，是应用程序运行的载体。进程是一种抽象的概念，从来没有统一的标准定义。</p><h4 id="进程的组成" tabindex="-1">进程的组成 <a class="header-anchor" href="#进程的组成" aria-label="Permalink to &quot;进程的组成&quot;">​</a></h4><p>进程一般由程序、数据集合和进程控制块三部分组成。</p><ul><li>程序用于描述进程要完成的功能，是控制进程执行的指令集；</li><li>数据集合是程序在执行时所需要的数据和工作区；</li><li>程序控制块(Program Control Block，简称PCB)，包含进程的描述信息和控制信息，是进程存在的唯一标志。</li></ul><h4 id="进程具有的特征" tabindex="-1">进程具有的特征： <a class="header-anchor" href="#进程具有的特征" aria-label="Permalink to &quot;进程具有的特征：&quot;">​</a></h4><ul><li>动态性：进程是程序的一次执行过程，是临时的，有生命期的，是动态产生，动态消亡的；</li><li>并发性：任何进程都可以同其他进程一起并发执行；</li><li>独立性：进程是系统进行资源分配和调度的一个独立单位；</li><li>结构性：进程由程序、数据和进程控制块三部分组成。</li></ul><h3 id="线程" tabindex="-1">线程 <a class="header-anchor" href="#线程" aria-label="Permalink to &quot;线程&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>是进程的一个执行单元，是进程内科调度实体。比进程更小的独立运行的基本单位。线程也被称为轻量级进程。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>进程中的一个执行任务（控制单元），负责当前进程中程序的执行。一个进程至少有一个线程，一个进程可以运行多个线程，多个线程可共享[数据]。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>与进程不同的是同类的多个线程共享进程的**堆**和**方法区**资源，但每个线程有自己的**程序计数器**、**虚拟机栈**和**本地方法栈**，所以系统在产生一个线程，或是在各个线程之间作切换工作时，负担要比进程小得多，也正因为如此，线程也被称为轻量级进程。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>在早期的操作系统中并没有线程的概念，进程是能拥有资源和独立运行的最小单位，也是程序执行的最小单位。任务调度采用的是时间片轮转的抢占式调度方式，而进程是任务调度的最小单位，每个进程有各自独立的一块内存，使得各个进程之间内存地址相互隔离。</p><p>后来，随着计算机的发展，对CPU的要求越来越高，进程之间的切换开销较大，已经无法满足越来越复杂的程序的要求了。于是就发明了线程。</p><p>线程是程序执行中一个单一的顺序控制流程，是程序执行流的最小单元，是处理器调度和分派的基本单位。一个进程可以有一个或多个线程，各个线程之间共享程序的内存空间(也就是所在进程的内存空间)。一个标准的线程由线程ID、当前指令指针(PC)、寄存器和堆栈组成。而进程由内存空间(代码、数据、进程空间、打开的文件)和一个或多个线程组成。</p><h4 id="任务调度" tabindex="-1">任务调度 <a class="header-anchor" href="#任务调度" aria-label="Permalink to &quot;任务调度&quot;">​</a></h4><p>线程是什么？要理解这个概念，需要先了解一下操作系统的一些相关概念。大部分操作系统(如Windows、Linux)的任务调度是采用时间片轮转的抢占式调度方式。</p><p>在一个进程中，当一个线程任务执行几毫秒后，会由操作系统的内核（负责管理各个任务）进行调度，通过硬件的计数器中断处理器，让该线程强制暂停并将该线程的寄存器放入内存中，通过查看线程列表决定接下来执行哪一个线程，并从内存中恢复该线程的寄存器，最后恢复该线程的执行，从而去执行下一个任务。 上述过程中，任务执行的那一小段时间叫做时间片，任务正在执行时的状态叫运行状态，被暂停的线程任务状态叫做就绪状态，意为等待下一个属于它的时间片的到来。</p><p>这种方式保证了每个线程轮流执行，由于CPU的执行效率非常高，时间片非常短，在各个任务之间快速地切换，给人的感觉就是多个任务在“同时进行”，这也就是我们所说的并发(别觉得并发有多高深，它的实现很复杂，但它的概念很简单，就是一句话：多个任务同时执行)。多任务运行过程的示意图如下：</p><img src="`+e+'" style="zoom:80%;"><h4 id="进程与线程的区别" tabindex="-1">进程与线程的区别 <a class="header-anchor" href="#进程与线程的区别" aria-label="Permalink to &quot;进程与线程的区别&quot;">​</a></h4><ol><li>线程是程序执行的最小单位，而进程是操作系统分配资源的最小单位；</li><li>一个进程由一个或多个线程组成，线程是一个进程中代码的不同执行路线；</li><li>进程之间相互独立，但同一进程下的各个线程之间共享程序的内存空间(包括代码段、数据集、堆等)及一些进程级的资源(如打开文件和信号)，某进程内的线程在其它进程不可见；</li><li>调度和切换：线程上下文切换比进程上下文切换要快得多。</li></ol><p><strong>线程与进程关系的示意图：</strong></p><img src="'+r+'" style="zoom:75%;"><p><strong>进程与线程的资源共享关系</strong></p><img src="'+e+'" style="zoom:80%;"><h4 id="单线程与多线程的关系" tabindex="-1">单线程与多线程的关系 <a class="header-anchor" href="#单线程与多线程的关系" aria-label="Permalink to &quot;单线程与多线程的关系&quot;">​</a></h4><p>总之，线程和进程都是一种抽象的概念，线程是一种比进程更小的抽象，线程和进程都可用于实现并发。 在早期的操作系统中并没有线程的概念，进程是能拥有资源和独立运行的最小单位，也是程序执行的最小单位。它相当于一个进程里只有一个线程，进程本身就是线程。所以线程有时被称为轻量级进程(Lightweight Process，LWP）。</p><p><strong>早期的操作系统只有进程，没有线程</strong></p><p>后来，随着计算机的发展，对多个任务之间上下文切换的效率要求越来越高，就抽象出一个更小的概念——线程，一般一个进程会有多个(也可是一个)线程。</p><p>线程的出现，使得一个进程可以有多个线程。</p><h4 id="多线程与多核" tabindex="-1">多线程与多核 <a class="header-anchor" href="#多线程与多核" aria-label="Permalink to &quot;多线程与多核&quot;">​</a></h4><p>上面提到的时间片轮转的调度方式说一个任务执行一小段时间后强制暂停去执行下一个任务，每个任务轮流执行。很多操作系统的书都说“同一时间点只有一个任务在执行”。那有人可能就要问双核处理器呢？难道两个核不是同时运行吗？</p><p>其实“同一时间点只有一个任务在执行”这句话是不准确的，至少它是不全面的。那多核处理器的情况下，线程是怎样执行呢？这就需要了解内核线程。</p><p>多核(心)处理器是指在一个处理器上集成多个运算核心从而提高计算能力，也就是有多个真正并行计算的处理核心，每一个处理核心对应一个内核线程。 内核线程（Kernel Thread，KLT）就是直接由操作系统内核支持的线程，这种线程由内核来完成线程切换，内核通过操作调度器对线程进行调度，并负责将线程的任务映射到各个处理器上。一般一个处理核心对应一个内核线程，比如单核处理器对应一个内核线程，双核处理器对应两个内核线程，四核处理器对应四个内核线程。</p><p>现在的电脑一般是双核四线程、四核八线程，是采用超线程技术将一个物理处理核心模拟成两个逻辑处理核心，对应两个内核线程，所以在操作系统中看到的CPU数量是实际物理CPU数量的两倍，如你的电脑是双核四线程，打开“任务管理器\\性能”可以看到4个CPU的监视器，四核八线程可以看到8个CPU的监视器。</p><h4 id="线程的生命周期" tabindex="-1">线程的生命周期 <a class="header-anchor" href="#线程的生命周期" aria-label="Permalink to &quot;线程的生命周期&quot;">​</a></h4><p>进程有五种状态，创建、就绪、运行、阻塞(等待)、退出。早期的进程相当于现在的只有单个线程的进程，那么现在的多线程也有五种状态，现在的多线程的生命周期与早期进程的生命周期类似</p><img src="'+t+'" style="zoom:80%;"><p>线程的生命周期:</p><ul><li>创建：一个新的线程被创建，等待该线程被调用执行；</li><li>就绪：时间片已用完，此线程被强制暂停，等待下一个属于它的时间片到来；</li><li>运行：此线程正在执行，正在占用时间片；</li><li>阻塞：也叫等待状态，等待某一事件(如IO或另一个线程)执行完；</li><li>退出：一个线程完成任务或者其他终止条件发生，该线程终止进入退出状态，退出状态释放该线程所分配的资源。</li></ul><h3 id="协程" tabindex="-1">协程 <a class="header-anchor" href="#协程" aria-label="Permalink to &quot;协程&quot;">​</a></h3><p>协程，英文Coroutines，是一种基于线程之上，但又比线程更加轻量级的存在，这种由程序员自己写程序来管理的轻量级线程叫做『用户空间线程』，具有对内核来说不可见的特性。</p><p>因为是自主开辟的异步任务，所以很多人也更喜欢叫它们纤程（Fiber），或者绿色线程（GreenThread）。正如一个进程可以拥有多个线程一样，一个线程也可以拥有多个协程。</p><img src="'+o+'" style="zoom:75%;"><h4 id="协程的目的" tabindex="-1">协程的目的 <a class="header-anchor" href="#协程的目的" aria-label="Permalink to &quot;协程的目的&quot;">​</a></h4><p>在传统的J2EE系统中都是基于每个请求占用一个线程去完成完整的业务逻辑（包括事务）。所以系统的吞吐能力取决于每个线程的操作耗时。如果遇到很耗时的I/O行为，则整个系统的吞吐立刻下降，因为这个时候线程一直处于阻塞状态，如果线程很多的时候，会存在很多线程处于空闲状态（等待该线程执行完才能执行），造成了资源应用不彻底。</p><p>最常见的例子就是JDBC（它是同步阻塞的），这也是为什么很多人都说数据库是瓶颈的原因。这里的耗时其实是让CPU一直在等待I/O返回，说白了线程根本没有利用CPU去做运算，而是处于空转状态。而另外过多的线程，也会带来更多的ContextSwitch开销。</p><p>对于上述问题，现阶段行业里的比较流行的解决方案之一就是单线程加上异步回调。其代表派是node.js以及Java里的新秀Vert.x。</p><p>而协程的目的就是当出现长时间的I/O操作时，通过让出目前的协程调度，执行下一个任务的方式，来消除ContextSwitch上的开销。</p><h4 id="协程的特点" tabindex="-1">协程的特点 <a class="header-anchor" href="#协程的特点" aria-label="Permalink to &quot;协程的特点&quot;">​</a></h4><ol><li>线程的切换由操作系统负责调度，协程由用户自己进行调度，因此减少了上下文切换，提高了效率。</li><li>线程的默认Stack大小是1M，而协程更轻量，接近1K。因此可以在相同的内存中开启更多的协程。</li><li>由于在同一个线程上，因此可以避免竞争关系而使用锁。</li><li>适用于被阻塞的，且需要大量并发的场景。但不适用于大量计算的多线程，遇到此种情况，更好实用线程去解决。</li></ol><h4 id="协程的原理" tabindex="-1">协程的原理 <a class="header-anchor" href="#协程的原理" aria-label="Permalink to &quot;协程的原理&quot;">​</a></h4><p>线程的切换由操作系统负责调度，协程由用户自己进行调度，因此减少了上下文切换，提高了效率。</p><p>线程的默认Stack大小是1M，而协程更轻量，接近1K。因此可以在相同的内存中开启更多的协程。</p><p>由于在同一个线程上，因此可以避免竞争关系而使用锁。</p><p>适用于被阻塞的，且需要大量并发的场景。但不适用于大量计算的多线程，遇到此种情况，更好实用线程去解决。</p><h4 id="协程与线程的比较" tabindex="-1">协程与线程的比较 <a class="header-anchor" href="#协程与线程的比较" aria-label="Permalink to &quot;协程与线程的比较&quot;">​</a></h4><img src="'+p+'" style="zoom:80%;"><h2 id="浏览器中的线程" tabindex="-1">浏览器中的线程 <a class="header-anchor" href="#浏览器中的线程" aria-label="Permalink to &quot;浏览器中的线程&quot;">​</a></h2><p>参考：<a href="https://juejin.cn/post/6991849728493256741" target="_blank" rel="noreferrer">深入理解浏览器中的进程与线程 - 掘金 (juejin.cn)</a></p>',62)]))}const f=l(h,[["render",c]]);export{q as __pageData,f as default};
